"""Pipeline worker stage."""

from typing import Callable, List
from channel import BoundedChannel


class StageWorker:
    def __init__(self, in_ch: BoundedChannel, out_ch: BoundedChannel, transform_fn: Callable[[int], int]):
        self.in_ch = in_ch
        self.out_ch = out_ch
        self.transform_fn = transform_fn

    def process_batch(self, max_items: int = 10) -> int:
        count = 0
        for _ in range(max_items):
            item = self.in_ch.get(timeout=0.05)
            if item is None:
                break
            res = self.transform_fn(item)
            if not self.out_ch.put(res, timeout=0.05):
                break
            count += 1
        return count

